const btnCtx = await browserjs(tabId, () => {
  const btn = document.querySelector('#advancedFilters .bed-filter-button[data-value="1"]');
  const ctx = ko.contextFor(btn);
  if (!ctx) return { error: "no context" };
  const getObs = (obj) => {
    const res = {};
    for (const k in obj) {
      if (typeof obj[k] === 'function' && obj[k].name === 'observable') {
        try { res[k] = obj[k](); } catch(e) { res[k] = 'err'; }
      } else if (typeof obj[k] !== 'function') {
        res[k] = obj[k];
      }
    }
    return res;
  };
  return {
    ctxKeys: Object.keys(ctx),
    dataKeys: Object.keys(ctx.$data || {}),
    dataVals: getObs(ctx.$data),
    rootKeys: Object.keys(ctx.$root || {})
  };
});
console.log(btnCtx);

